let touchStart=null;renderer.domElement.addEventListener('pointerdown',e=>{touchStart={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;if(Math.max(Math.abs(dx),Math.abs(dy))>25){if(Math.abs(dx)>Math.abs(dy))act(dx<0?'left':'right');else act(dy<0?'jump':'slide')}touchStart=null});

// Duplicate the complete station set so the track can loop without a visible seam.
const secondWorld=world.clone(true);secondWorld.position.z=-138;scene.add(secondWorld);
function spawnWave(){
 const laneA=Math.floor(Math.random()*3),roll=Math.random();
 if(roll<.34){makeObstacle('barrier',laneA,-72);addCoins(laneA===1?0:1,-56,5,2.1,false)}
 else if(roll<.64){makeObstacle('gate',laneA,-72);const safe=(laneA+1+Math.floor(Math.random()*2))%3;addCoins(safe,-58,5,2.1,false)}
 else if(roll<.84){makeObstacle('train',laneA,-72);const safe=(laneA+1)%3;addCoins(safe,-57,6,2.2,false)}
 else{addCoins(laneA,-72,8,2.1,true)}
}
function updateGame(dt){
 if(runState!=='playing')return;
 elapsed+=dt;distance+=speed*dt*.72;speed=Math.min(22,13+Math.floor(distance/180)*.75);
 spawnTimer-=dt;coinTimer-=dt;if(spawnTimer<=0){spawnWave();spawnTimer=Math.max(1.7,3.15-(speed-13)*.075)+Math.random()*.55}if(coinTimer<=0){if(Math.random()<.54){const l=Math.floor(Math.random()*3);addCoins(l,-67,5,2.35,false)}coinTimer=2.35+Math.random()*1.25}
 world.position.z+=speed*dt;secondWorld.position.z+=speed*dt;if(world.position.z>=138)world.position.z-=276;if(secondWorld.position.z>=138)secondWorld.position.z-=276;
 for(const o of obstacles)o.position.z+=speed*dt;for(const c of coins){c.position.z+=speed*dt;c.rotation.z+=dt*2.7;c.rotation.y+=dt*.7;}
 obstacles=obstacles.filter(o=>{if(o.position.z>12){scene.remove(o);return false}return true});coins=coins.filter(c=>{if(c.userData.taken)return false;if(c.position.z>12){scene.remove(c);return false}return true});
 jumpTime=Math.max(0,jumpTime-dt);slideTime=Math.max(0,slideTime-dt);
 const jumpProgress=jumpTime>0?1-jumpTime/.78:0;runner.position.y=jumpTime>0?Math.sin(jumpProgress*Math.PI)*1.6:0;
 runner.position.x+=(lanes[lane]-runner.position.x)*Math.min(1,dt*13);
 const running=elapsed*speed*.55;body.position.y=slideTime>0?-.3:Math.abs(Math.sin(running*1.65))*.065;body.rotation.x=slideTime>0?-.55:Math.sin(running*1.65)*.035;
 for(let i=0;i<2;i++){const swing=Math.sin(running*1.65+i*Math.PI)*.72;legs[i].rotation.x=slideTime>0?-.5:swing;arms[i].rotation.x=slideTime>0?.6:-swing*.75;}
 body.scale.y=slideTime>0?.72:1;
 for(const o of obstacles){if(Math.abs(o.position.z-runner.position.z)<1.02&&Math.abs(o.position.x-runner.position.x)<1.05){const safe=o.userData.type==='barrier'&&runner.position.y>.78||o.userData.type==='gate'&&slideTime>0;if(!safe){endGame();break}}}
 for(const c of coins){if(!c.userData.taken&&Math.abs(c.position.z-runner.position.z)<1.05&&Math.abs(c.position.x-runner.position.x)<1.05&&Math.abs(c.position.y-(runner.position.y+1.05))<1.6){c.userData.taken=true;scene.remove(c);coinCount++;flashToast('+1 COIN')}}
 ui.distance.innerHTML=`${String(Math.floor(distance)).padStart(4,'0')} <small style="font:500 9px 'DM Sans';color:#9db6c0">m</small>`;ui.coins.textContent=`◉ ${coinCount}`;ui.progress.style.width=`${Math.floor(distance%240/240*100)}%`;ui.speed.textContent=`SPEED ${(speed/13).toFixed(1)}×`;
 if(elapsed>4)ui.hint.style.opacity='0';
}
let last=performance.now();function frame(now){const dt=Math.min(.04,(now-last)/1000);last=now;updateGame(dt);if(shake>0){shake=Math.max(0,shake-dt);camera.position.x=(Math.random()-.5)*shake*1.5} else camera.position.x+=(0-camera.position.x)*.1;camera.lookAt(0,1.05,-4);renderer.render(scene,camera);requestAnimationFrame(frame)}requestAnimationFrame(frame);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script>
</body>
</html>

